'use client';
import { useState } from 'react';
import Navbar from '@/components/Navbar';
import { Search, Filter, Clock, Home, BadgeCheck } from 'lucide-react';

const MOCK_TESTS = [
  { id: 1, name: 'Full Body Checkup', price: 2999, discountPrice: 1499, discount: '50% OFF', verified: true, time: '24 Hours', homeCollection: true },
  { id: 2, name: 'Thyroid Profile (Total)', price: 800, discountPrice: 399, discount: '50% OFF', verified: true, time: '12 Hours', homeCollection: true },
  { id: 3, name: 'Complete Blood Count (CBC)', price: 400, discountPrice: 250, discount: '37% OFF', verified: true, time: '6 Hours', homeCollection: false },
  { id: 4, name: 'Lipid Profile', price: 900, discountPrice: 450, discount: '50% OFF', verified: true, time: '12 Hours', homeCollection: true },
  { id: 5, name: 'Diabetes Screening', price: 500, discountPrice: 199, discount: '60% OFF', verified: true, time: '6 Hours', homeCollection: true },
];

export default function LabTests() {
  const [searchTerm, setSearchTerm] = useState('');
  
  const filteredTests = MOCK_TESTS.filter(test => 
    test.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <main style={{ paddingBottom: '100px' }}>
      <Navbar />
      
      <div className="container" style={{ paddingTop: 'calc(var(--header-height) + 2rem)' }}>
        
        {/* Header & Search */}
        <div style={{ marginBottom: '2rem' }}>
          <h1 style={{ marginBottom: '1rem' }}>Book Lab Tests</h1>
          <div className="glass" style={{ display: 'flex', gap: '1rem', padding: '1rem', alignItems: 'center' }}>
             <Search size={20} color="var(--primary)" />
             <input 
                type="text"
                placeholder="Search for blood tests, scans, or packages..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                style={{ background: 'transparent', border: 'none', color: '#fff', fontSize: '1rem', outline: 'none', flex: 1 }}
             />
             <div style={{ width: '1px', height: '20px', background: 'rgba(255,255,255,0.1)' }}></div>
             <button style={{ background: 'transparent', border: 'none', color: 'var(--text-muted)', display: 'flex', alignItems: 'center', gap: '5px', cursor: 'pointer' }}>
               <Filter size={18} /> Filters
             </button>
          </div>
        </div>

        {/* Listings */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(350px, 1fr))', gap: '1.5rem' }}>
          {filteredTests.map((test) => (
            <div key={test.id} className="glass" style={{ padding: '1.5rem', position: 'relative', overflow: 'hidden' }}>
              
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '1rem' }}>
                <span className="badge-discount">{test.discount}</span>
                {test.verified && <span className="verified-tag"><BadgeCheck size={14} /> NABL Certified</span>}
              </div>

              <h3 style={{ fontSize: '1.2rem', marginBottom: '0.5rem' }}>{test.name}</h3>
              
              <div style={{ display: 'flex', gap: '1rem', marginBottom: '1.5rem', fontSize: '0.9rem', color: 'var(--text-muted)' }}>
                 <div style={{ display: 'flex', alignItems: 'center', gap: '5px' }}>
                    <Clock size={14} /> Report in {test.time}
                 </div>
                 {test.homeCollection && (
                   <div style={{ display: 'flex', alignItems: 'center', gap: '5px' }}>
                      <Home size={14} /> Home Collection
                   </div>
                 )}
              </div>

              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'end', marginTop: 'auto' }}>
                 <div>
                    <span style={{ textDecoration: 'line-through', color: 'var(--text-muted)', fontSize: '0.9rem' }}>₹{test.price}</span>
                    <div style={{ fontSize: '1.5rem', fontWeight: 'bold', color: 'var(--primary)' }}>₹{test.discountPrice}</div>
                 </div>
                 <button className="btn btn-outline">Add to Cart</button>
              </div>

            </div>
          ))}
        </div>

      </div>

      <style jsx>{`
        .badge-discount {
          background: rgba(255, 159, 67, 0.15);
          color: var(--accent);
          font-size: 0.8rem;
          padding: 4px 10px;
          border-radius: 4px;
          font-weight: 700;
        }
        .verified-tag {
          display: flex; 
          align-items: center; 
          gap: 4px; 
          color: var(--primary); 
          font-size: 0.8rem;
          font-weight: 600;
        }
      `}</style>
    </main>
  );
}
